const BASE=new URL('./',self.registration.scope).pathname;
const CACHE='awe-faith-shell-v18';
const APP_FILES=['apphub/index.html','apphub/styles.css','apphub/app.js','watchmen/index.html','watchmen/styles.css','watchmen/app.js','hidden-in-my-heart/index.html','hidden-in-my-heart/styles.css','hidden-in-my-heart/app.js','bible-verse-sprint/index.html','bible-verse-sprint/styles.css','bible-verse-sprint/app.js','one-year-in-the-word/index.html','one-year-in-the-word/styles.css','one-year-in-the-word/app.js','sat-vocabulary-sprint/index.html','sat-vocabulary-sprint/styles.css','sat-vocabulary-sprint/app.js','daber-hebrew-coach/index.html','daber-hebrew-coach/styles.css','daber-hebrew-coach/app.js','asl-sign-coach/index.html','asl-sign-coach/styles.css','asl-sign-coach/app.js','off-market-deal-finder/index.html','off-market-deal-finder/styles.css','off-market-deal-finder/app.js','kdp-launch-assistant/index.html','kdp-launch-assistant/styles.css','kdp-launch-assistant/app.js','jobpilot-ai/index.html','jobpilot-ai/styles.css','jobpilot-ai/app.js','po-ai-daily/index.html','po-ai-daily/styles.css','po-ai-daily/app.js','sellsnap/index.html','sellsnap/styles.css','sellsnap/app.js','pulse-path/index.html','pulse-path/styles.css','pulse-path/app.js','megastats-predictor/index.html','megastats-predictor/styles.css','megastats-predictor/app.js'];
const SHELL=['','index.html','styles.css','app.js','analytics.js','manifest.webmanifest','icon.svg','icon-192.png','icon-512.png',...APP_FILES].map(p=>BASE+p);
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL))));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k))))));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(u.origin!==location.origin||u.pathname===BASE+'catalog.json')return;e.respondWith(caches.match(e.request).then(hit=>hit||fetch(e.request).then(r=>{const clone=r.clone();caches.open(CACHE).then(c=>c.put(e.request,clone));return r})))});
